package gost34112012256

import (
	"bytes"
	"testing"
)

func TestKDFGOSTR34112012256(t *testing.T) {
	kdf := NewKDF([]byte{
		0x00, 0x01, 0x02, 0x03, 0x04, 0x05, 0x06, 0x07,
		0x08, 0x09, 0x0a, 0x0b, 0x0c, 0x0d, 0x0e, 0x0f,
		0x10, 0x11, 0x12, 0x13, 0x14, 0x15, 0x16, 0x17,
		0x18, 0x19, 0x1a, 0x1b, 0x1c, 0x1d, 0x1e, 0x1f,
	})
	derived := kdf.Derive(
		nil,
		[]byte{0x26, 0xbd, 0xb8, 0x78},
		[]byte{0xaf, 0x21, 0x43, 0x41, 0x45, 0x65, 0x63, 0x78},
	)
	var dst [Size]byte
	derivedInto := kdf.DeriveInto(
		dst[:0],
		[]byte{0x26, 0xbd, 0xb8, 0x78},
		[]byte{0xaf, 0x21, 0x43, 0x41, 0x45, 0x65, 0x63, 0x78},
	)
	if !bytes.Equal(derived, derivedInto) {
		t.Fatal("DeriveInto mismatch")
	}
	if !bytes.Equal(derived, []byte{
		0xa1, 0xaa, 0x5f, 0x7d, 0xe4, 0x02, 0xd7, 0xb3,
		0xd3, 0x23, 0xf2, 0x99, 0x1c, 0x8d, 0x45, 0x34,
		0x01, 0x31, 0x37, 0x01, 0x0a, 0x83, 0x75, 0x4f,
		0xd0, 0xaf, 0x6d, 0x7c, 0xd4, 0x92, 0x2e, 0xd9,
	}) {
		t.FailNow()
	}
}

func TestKDFTreeRFC7836(t *testing.T) {
	key := make([]byte, 32)
	for i := range key {
		key[i] = byte(i)
	}
	kdf := NewKDF(key)
	label := []byte{0x26, 0xbd, 0xb8, 0x78}
	seed := []byte{0xaf, 0x21, 0x43, 0x41, 0x45, 0x65, 0x63, 0x78}
	var first [32]byte
	if err := kdf.DeriveTreeInto(first[:], label, seed, 1); err != nil {
		t.Fatal(err)
	}
	if !bytes.Equal(first[:], kdf.Derive(nil, label, seed)) {
		t.Fatal("RFC 7836 KDF_TREE R=1 L=256 differs from KDF vector")
	}
	var multiple [64]byte
	if err := kdf.DeriveTreeInto(multiple[:], label, seed, 1); err != nil {
		t.Fatal(err)
	}
	if bytes.Equal(multiple[:32], first[:]) || bytes.Equal(multiple[:32], multiple[32:]) {
		t.Fatal("counter or encoded output length was ignored")
	}
	if err := kdf.DeriveTreeInto(multiple[:], label, seed, 0); err == nil {
		t.Fatal("invalid counter length accepted")
	}
}
